287		m.results = netcheck.ResultsOf(check(netcheck.CheckResolve, netcheck.OK, "kept"))
288		m = traceHops(t, m, 2)
289		gen := m.pathModel.gen
290	
291		m = feed(t, m, testutil.Key("esc"))
292		if m.state != StateTrace {
293			t.Fatalf("state = %v after the first esc, want StateTrace", m.state)
294		}
295		pm := m.pathModel
296		if pm.running() || pm.result == nil || pm.result.Outcome != nettrace.OutcomeCancelled {
297			t.Errorf("running=%v result=%+v, want a canceled run", pm.running(), pm.result)
298		}
299		if pm.gen == gen {
300			t.Error("the run's generation did not change: its late messages would still land")
301		}
302		if got := pmHopTTLs(pm); !slices.Equal(got, []int{1, 2}) {
303			t.Errorf("hops = %v after cancel, want [1 2] kept", got)
304		}
305		if m.Running() {
306			t.Error("Running() = true after the cancel")
307		}
308	
309		m = feed(t, m, testutil.Key("esc"))
310		if m.state != StateInput {
311			t.Fatalf("state = %v after the second esc, want StateInput", m.state)
312		}
