39	// traceHops feeds n router hops of the current run.
40	func traceHops(t *testing.T, m *Model, n int) *Model {
41		t.Helper()
42		for ttl := 1; ttl <= n; ttl++ {
43			m = feed(t, m, pathHopMsg{gen: m.pathModel.gen, hop: hopOf(ttl, nettrace.HopRouter)})
44		}
45		return m
46	}
47	
48	func traceEnded(t *testing.T, m *Model) *Model {
49		t.Helper()
50		// The engine's final Result carries every hop; handleDone replaces the rows by them.
51		res := nettrace.Result{Outcome: nettrace.OutcomeReached, Hops: slices.Clone(m.pathModel.hops)}
52		return feed(t, m, pathDoneMsg{gen: m.pathModel.gen, result: res})
53	}
