60	// tracePhases returns one fresh model per phase of a trace, so no case sees the
61	// mutations of another (a Model is updated in place).
62	func tracePhases(t *testing.T) map[string]*Model {
63		t.Helper()
64		build := func(end func(*testing.T, *Model) *Model) *Model {
65			m, _, _ := traceLevelModel(t, traceLevelHost)
66			m = traceHops(t, m, 2)
67			if end == nil {
68				return m
69			}
70			return end(t, m)
71		}
72		return map[string]*Model{
73			"running":  build(nil),
74			"done":     build(traceEnded),
75			"canceled": build(traceCanceled),
76		}
77	}
